  },
  {
    id: 10,
    title: "Desert Lizard Wildlife",
    category: "Nature",
    filename: "images (6).jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1534188753412-3e26d0d618d6?w=600"
  },
  {
    id: 11,
    title: "Studio Male Portrait",
    category: "Portrait",
    filename: "images (7).jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=600"
  },
  {
    id: 12,
    title: "Green Hills Landscape",
    category: "Travel",
    filename: "images.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=600"
  },
  {
    id: 13,
    title: "Sunlit Forest Rays",
    category: "Nature",
    filename: "nature-background-high-resolution-wallpaper-for-a-serene-and-calming-vibe-free-photo.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=600"
  },
  {
    id: 14,
