    category: "Nature",
    filename: "pexels-ankit-rainloure-1425442-35771810.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1448375240586-882707db888b?w=600"
  },
  {
    id: 15,
    title: "Red Bird In Flight",
    category: "Nature",
    filename: "pexels-dmytkopl-38601716.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1452570053594-1b985d6ea890?w=600"
  },
  {
    id: 16,
    title: "Autumn Tree Avenue",
    category: "Nature",
    filename: "pexels-efrem-efre-2786187-29046353.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600"
  },
  {
    id: 17,
    title: "Moody Forest Light",
    category: "Nature",
    filename: "pexels-josh-a-d-4467879-16636173.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1511497584788-8767611136f6?w=600"
  },
  {
    id: 18,
    title: "Soft Floral Composition",
    category: "Product",
    filename: "pexels-khadija-qasanova-376394062-20295105.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1490750967868-88aa4486c946?w=600"
  },
  {
    id: 19,
    title: "Coastal Cliff View",
    category: "Travel",
    filename: "photo-1544954617-f5c6b0d16164.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600"
  },
  {
    id: 20,
    title: "Sunlit Botanical Garden",
    category: "Nature",
    filename: "photo-1457089328109-e5d9bd499191.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1465146344425-f00d5f5c8f07?w=600"
  },
  {
    id: 21,
    title: "Golden Hour Valley",
    category: "Nature",
    filename: "photo-1472214103451-9374bd1c798e.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=600"
  },
  {
    id: 22,
    title: "Wild Orange Blossoms",
    category: "Nature",
    filename: "photo-1684087554249-0021c9c85fc9.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1508610048659-a06b669e3321?w=600"
  },
  {
    id: 23,
    title: "Purple Canopy Forest",
    category: "Nature",
    filename: "photo-1693985007521-e08e64770947.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=600"
  },
  {
    id: 24,
    title: "Blue Hour Meadow",
    category: "Nature",
    filename: "photo-1695004672476-0c1e8d7a7e79.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=600"
  },
  {
    id: 25,
    title: "Fashion Studio Model",
    category: "Fashion",
    filename: "premium_photo-1679064458881-76904cf6d1aa.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=600"
  },
  {
    id: 26,
    title: "Sunset Over Calm Waters",
    category: "Nature",
    filename: "Sunset-ball.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1495616811223-4d98c6e9c869?w=600"
  },
  {
    id: 27,
    title: "Red Geranium Flowers",
    category: "Nature",
    filename: "types-of-red-flowers-geranium.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1508610048659-a06b669e3321?w=600"
  },
  {
    id: 28,
    title: "Wildlife Safari Predators",
    category: "Nature",
    filename: "Wildlife+Photography+by+Kathy+Karn+01.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1534188753412-3e26d0d618d6?w=600"
  }
];

const PACKAGES = [
  { id: "basic", name: "Basic", price: 150, duration: "2 Hours", features: ["1 Photographer", "15 Edited Photos", "Online Gallery"] },
  { id: "standard", name: "Standard", price: 350, duration: "4 Hours", features: ["1 Photographer", "40 Edited Photos", "Online Gallery", "1 Canvas Print"] },
  { id: "premium", name: "Premium", price: 700, duration: "Full Day", features: ["2 Photographers", "All Edited Photos", "Online Gallery", "Album + Prints"] },
  { id: "custom", name: "Custom", price: 0, duration: "Flexible", features: ["Custom Hours", "Custom Deliverables", "Tailored Locations"] }
];

// Helper function to resolve paths regardless of Images/images folder casing
const getImagePath = (filename) => {
  return process.env.PUBLIC_URL + `/images/${filename}`;
};

export default function App() {
  const [activeTab, setActiveTab] = useState("home");
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [theme, setTheme] = useState(() => localStorage.getItem("theme") || "dark");
  const [favorites, setFavorites] = useState(() => {
    const saved = localStorage.getItem("fav_photos");
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedCategory, setSelectedCategory] = useState("All");
  const [searchTerm, setSearchTerm] = useState("");
  const [activeLightbox, setActiveLightbox] = useState(null);

  const [selectedPackage, setSelectedPackage] = useState(PACKAGES[0].id);
  const [extraHours, setExtraHours] = useState(0);
  const [includePrints, setIncludePrints] = useState(false);
  const [formData, setFormData] = useState({ name: "", email: "", date: "", time: "" });
  const [isSubmitted, setIsSubmitted] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth <= 768);
      if (window.innerWidth > 768) setIsMenuOpen(false);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    localStorage.setItem("theme", theme);
    document.body.className = theme;
  }, [theme]);

  useEffect(() => {
    localStorage.setItem("fav_photos", JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id) => {
    setFavorites((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const currentPkg = PACKAGES.find((p) => p.id === selectedPackage) || PACKAGES[0];
  const calculatedTotal = currentPkg.price + extraHours * 50 + (includePrints ? 75 : 0);

  const handleBookingSubmit = (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.date || !formData.time) {
      alert("Please fill in all mandatory fields.");
      return;
    }
    setIsSubmitted(true);
  };

  const filteredImages = GALLERY_IMAGES.filter((img) => {
    const matchesCat = selectedCategory === "All" || img.category === selectedCategory;
    const matchesSearch = img.title.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCat && matchesSearch;
  });

  const displayedImages = activeTab === "favorites"
    ? GALLERY_IMAGES.filter((img) => favorites.includes(img.id))
    : filteredImages;

  return (
    <div className={`app-container ${theme}`}>
      {/* Sticky Navbar */}
      <nav className="navbar">
        <div className="nav-brand">
          <span>📷</span> SHUTTER STORIES
        </div>

        {isMobile && (
          <button
            className="hamburger-btn"
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            aria-label="Toggle Navigation Menu"
          >
            ☰
          </button>
        )}

        <ul
          className="nav-links"
          style={{
            display: isMobile ? (isMenuOpen ? "flex" : "none") : "flex",
            flexDirection: isMobile ? "column" : "row"
          }}
        >
          {["home", "gallery", "packages", "booking", "favorites"].map((tab) => (
            <li key={tab}>
              <button
                className={activeTab === tab ? "active" : ""}
                onClick={() => {
                  setActiveTab(tab);
                  setIsMenuOpen(false);
                }}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)}{" "}
                {tab === "favorites" ? `(${favorites.length})` : ""}
              </button>
            </li>
          ))}
          <li>
            <button
              className="theme-toggle"
              onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
            >
              {theme === "dark" ? "☀️ Light" : "🌙 Dark"}
            </button>
          </li>
        </ul>
      </nav>

      {/* Hero Section */}
      {activeTab === "home" && (
        <section className="hero-section">
          <div className="hero-backdrop">
            <img
              src={getImagePath("hero-bg.jpg")}
              alt="Photographer hero backdrop"
              onError={(e) => {
                e.target.onerror = null;
                // Try alternate capitalized directory if main path fails
                e.target.src = process.env.PUBLIC_URL + "/Images/hero-bg.jpg";
              }}
            />
            <div className="hero-overlay"></div>
          </div>
          <div className="hero-content">
            <p className="subtitle">CAPTURING MOMENTS</p>
            <h1>Stories Through My Lens</h1>
            <p className="description">
              Professional photography services for people, places, and moments that matter.
            </p>
            <div className="hero-buttons">
              <button className="btn-primary" onClick={() => setActiveTab("gallery")}>
                View Portfolio
              </button>
              <button className="btn-secondary" onClick={() => setActiveTab("booking")}>
                Book Session
              </button>
            </div>
          </div>
        </section>
      )}

      {/* Portfolio / Favorites Gallery */}
      {(activeTab === "home" || activeTab === "gallery" || activeTab === "favorites") && (
        <section className="gallery-section">
          <h2>{activeTab === "favorites" ? "Your Favorites" : "Portfolio Gallery"}</h2>

          {activeTab !== "favorites" && (
            <>
              <div className="filter-bar">
                {CATEGORIES.map((cat) => (
                  <button
                    key={cat}
                    className={selectedCategory === cat ? "filter-btn active" : "filter-btn"}
                    onClick={() => setSelectedCategory(cat)}
                  >
                    {cat}
                  </button>
                ))}
              </div>

              <div className="search-box">
                <input
                  type="text"
                  placeholder="Search photo titles..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </>
          )}

          <div className="gallery-grid">
            {displayedImages.length > 0 ? (
              displayedImages.map((img) => {
                const isFav = favorites.includes(img.id);
                return (
                  <div className="gallery-card" key={img.id}>
                    <div className="img-wrapper">
                      <img
                        src={getImagePath(img.filename)}
                        alt={img.title}
                        onError={(e) => {
                          e.target.onerror = null;
                          // Fallback to /Images/ if /images/ fails
                          e.target.src = process.env.PUBLIC_URL + `/Images/${img.filename}`;
                        }}
                        onClick={() => setActiveLightbox(img)}
                      />
                    </div>
                    <div className="card-info">
                      <div className="card-text">
                        <h4>{img.title}</h4>
                        <span className="tag">{img.category}</span>
                      </div>
                      <button className="fav-btn" onClick={() => toggleFavorite(img.id)}>
                        {isFav ? "❤️" : "🤍"}
                      </button>
                    </div>
                  </div>
                );
              })
            ) : (
              <p className="no-data">No matching photos found in this section.</p>
            )}
          </div>
        </section>
      )}

      {/* Packages Section */}
      {(activeTab === "home" || activeTab === "packages") && (
        <section className="packages-section">
          <h2>Packages & Pricing</h2>
          <div className="packages-grid">
            {PACKAGES.map((pkg) => (
              <div key={pkg.id} className="package-card">
                <h3>{pkg.name}</h3>
                <p className="price">{pkg.price > 0 ? `$${pkg.price}` : "Custom Quote"}</p>
                <p className="duration">{pkg.duration}</p>
                <ul>
                  {pkg.features.map((feat, idx) => (
                    <li key={idx}>✓ {feat}</li>
                  ))}
                </ul>
                <button
                  className="btn-primary"
                  onClick={() => {
                    setSelectedPackage(pkg.id);
                    setActiveTab("booking");
                  }}
                >
                  Select Package
                </button>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Booking & Dynamic Calculator */}
      {(activeTab === "home" || activeTab === "booking") && (
        <section className="booking-section">
          <h2>Book a Photography Session</h2>
          <form onSubmit={handleBookingSubmit} className="booking-form">
            <label>Package Tier:</label>
            <select value={selectedPackage} onChange={(e) => setSelectedPackage(e.target.value)}>
              {PACKAGES.map((pkg) => (
                <option key={pkg.id} value={pkg.id}>
                  {pkg.name} (${pkg.price})
                </option>
              ))}
            </select>

            <label>Additional Hours ($50/hr):</label>
            <input
              type="number"
              min="0"
              max="10"
              value={extraHours}
              onChange={(e) => setExtraHours(Number(e.target.value))}
            />

            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={includePrints}
                onChange={(e) => setIncludePrints(e.target.checked)}
              />
              Include Canvas Print Package (+$75)
            </label>

            <input
              type="text"
              placeholder="Your Full Name"
              required
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            />

            <input
              type="email"
              placeholder="Your Email Address"
              required
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            />

            <div className="datetime-group">
              <input
                type="date"
                required
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
              />
              <input
                type="time"
                required
                value={formData.time}
                onChange={(e) => setFormData({ ...formData, time: e.target.value })}
              />
            </div>

            <div className="price-display">
              Total Cost Estimate: <strong>${calculatedTotal}</strong>
            </div>

            <button type="submit" className="btn-primary">
              Confirm & Book Session
            </button>
          </form>
        </section>
      )}

      {/* Image Lightbox Modal */}
      {activeLightbox && (
        <div className="lightbox-overlay" onClick={() => setActiveLightbox(null)}>
          <div className="lightbox-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setActiveLightbox(null)}>
              ✕
            </button>
            <img
              src={getImagePath(activeLightbox.filename)}
              alt={activeLightbox.title}
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = process.env.PUBLIC_URL + `/Images/${activeLightbox.filename}`;
              }}
            />
            <h3>{activeLightbox.title}</h3>
            <p>Category: {activeLightbox.category}</p>
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      {isSubmitted && (
        <div className="popup-overlay">
          <div className="popup-card">
            <h3>Session Reserved!</h3>
            <p>
              Thank you, {formData.name}. Your session is booked for {formData.date} at{" "}
              {formData.time}.
            </p>
            <p>
              Estimated Amount: <strong>${calculatedTotal}</strong>
            </p>
            <button className="btn-primary" onClick={() => setIsSubmitted(false)}>
              Done
            </button>
          </div>
        </div>
      )}

      <footer className="footer">
        <p>© 2026 Shutter Stories Photography. All rights reserved.</p>
      </footer>
    </div>
  );
}
